import {MayaService,languages,copy} from './maya-core.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const apiFetch=(...args)=>(window.mlawApi||fetch)(...args);
export async function openMaya({modal,read,write,mode,refresh,voiceConfigured,toast}){
 let lang='en',session,response,busy=false,recorder,stream,audio,history=[];
 const demo=new MayaService({read,write,demo:true,challenge:async()=>{},verify:async(s,code)=>code==='314159'&&read().matters.some(m=>m.id===s.reference)});
 async function api(path,data){const r=await apiFetch('/api/reception/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error||'Reception service unavailable');return d}
 modal('M LAW / MAYA',`<div class="maya-layout"><aside class="maya-profile"><div class="maya-portrait"><svg viewBox="0 0 280 320" role="img" aria-label="Illustrated identity for Maya, the AI receptionist"><defs><linearGradient id="maya-bg" x2="1" y2="1"><stop stop-color="#e4cfb2"/><stop offset="1" stop-color="#6d8b7c"/></linearGradient></defs><circle cx="140" cy="147" r="125" fill="url(#maya-bg)"/><path d="M66 238C31 162 67 56 141 55c80-4 111 99 74 186" fill="#283a35"/><path d="M40 320q8-83 66-92l34 19 34-19q61 12 68 92" fill="#ece6d5"/><path d="M117 199v36q24 35 47 0v-36" fill="#b88769"/><ellipse cx="141" cy="141" rx="57" ry="77" fill="#d8ac89"/><path d="M82 131q16-15 28-57 49 48 95 57-7-83-64-77-59 1-59 77" fill="#283a35"/><path d="M106 143q10-5 19 0m33 0q10-5 19 0" fill="none" stroke="#473c32" stroke-width="3" stroke-linecap="round"/><path d="M140 149l-4 24h10" fill="none" stroke="#b17d5b" stroke-width="2"/><path d="M122 190q18 13 37-1" fill="none" stroke="#905d52" stroke-width="3" stroke-linecap="round"/><path d="M86 146q-7 32 1 42" fill="none" stroke="#e7cc9e" stroke-width="5"/><path d="M196 143q9 43-12 59l-23 2" fill="none" stroke="#e7cc9e" stroke-width="4"/><rect x="150" y="200" width="18" height="8" rx="4" fill="#e7cc9e"/><path d="M106 230l35 48-28 42M174 230l-33 48 26 42" fill="none" stroke="#b5b8a1" stroke-width="2"/></svg></div><p class="eyebrow">YOUR FIRST CONNECTION</p><h2>Meet <em>Maya.</em></h2><p>A little warmth.<br>A clearer next step.</p><div class="maya-wave">${Array.from({length:22},(_,i)=>`<i style="--n:${i%7}"></i>`).join('')}</div><button class="button light small" id="mayaSample">Listen to her voice ◌</button><span class="maya-disclosure">AI receptionist · original illustrated identity<br>${mode==='server'?'Private service workspace':'Interactive demo · fictional information only'}</span></aside><section class="maya-conversation"><div class="chat-controls"><select id="mayaLanguage" aria-label="Maya language">${Object.entries(languages).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><span class="status" id="mayaConnection">${mode==='server'?'PRIVATE RECEPTION':'DEMONSTRATION'}</span></div><div id="mayaMessages" class="messages" aria-live="polite"></div><div id="mayaChoices" class="maya-choices"></div><div id="mayaHint" class="subtle"></div><form id="mayaForm" class="assistant-box"><input id="mayaInput" autocomplete="off" aria-label="Message Maya" placeholder="Type your response…" maxlength="2000" required><button class="button dark small" id="mayaSend" aria-label="Send to Maya">↗</button></form><div class="maya-controls"><button id="mayaSpeak" class="text-button">Read response ◌</button><button id="mayaMic" class="text-button">Hold a voice turn ♩</button><button id="mayaRestart" class="text-button">Start again ↻</button></div><p class="subtle" style="font-size:9px">No call is connected to the firm’s telephone number. Calendar reservations stay inside this workspace. Case updates require verification; legal advice stays with your attorney.</p></section></div>`);
 const $=s=>document.querySelector(s),dialog=$('#modal');dialog.classList.add('maya-shell');
 const cleanup=()=>{dialog.classList.remove('maya-shell');window.speechSynthesis?.cancel();audio?.pause();stream?.getTracks().forEach(t=>t.stop());if(recorder?.state==='recording')recorder.stop()};dialog.addEventListener('close',cleanup,{once:true});
 function draw(){const c=copy[lang];$('#mayaSample').textContent=['en','es','hi'].includes(lang)?'Listen · '+languages[lang]+' ◌':'Listen · English sample ◌';$('#mayaMessages').innerHTML=history.map(m=>`<div class="message ${m.user?'user':''}" dir="auto">${esc(m.text)}</div>`).join('');$('#mayaMessages').scrollTop=99999;$('#mayaChoices').innerHTML=(response.choices||[]).map(ch=>`<button type="button" data-choice="${esc(ch.action)}">${esc(ch.label)}</button>`).join('');$('#mayaHint').textContent=response.demoCode?'Fictional demo: ML-2601 · verification code 314159. This is not identity verification for real clients.':response.originalLanguage?'Approved update shown in its original language; no unreviewed translation.':'';$('#mayaRestart').textContent=c.restart+' ↻';$('#mayaInput').placeholder= response.step==='code'?'••••••':'…';$('#mayaInput').type=response.step==='code'?'password':'text';$('#mayaMic').disabled=!voiceConfigured||mode!=='server';$('#mayaMic').title=voiceConfigured?'Microphone audio is sent to the firm’s voice service':'Complete voice setup to enable microphone conversations';}
 async function start(){if(busy)return;busy=true;try{response=mode==='server'?await api('start',{language:lang}):demo.start(lang);session=response.sessionId;history=[{text:response.text}];draw()}catch(e){toast(e.message)}finally{busy=false}}
 async function send(text='',action=''){if(busy)return;busy=true;$('#mayaSend').disabled=true;history.push({user:true,text:response.step==='code'?'••••••':text||response.choices?.find(c=>c.action===action)?.label||action});try{response=mode==='server'?await api('message',{sessionId:session,text,action}):await demo.send(session,{text,action});history.push({text:response.text+(response.summary?'\n\n'+Object.entries(response.summary).filter(([key])=>key!=='start').map(([,value])=>value).join('\n'):'')+(response.receipt?'\n\n'+response.receipt.id+(response.receipt.when?'\n'+response.receipt.when:''):'')});if(mode==='server')await refresh();draw()}catch(e){history.push({text:e.message});draw()}finally{busy=false;if($('#mayaSend'))$('#mayaSend').disabled=false}}
 $('#mayaForm').onsubmit=e=>{e.preventDefault();const input=$('#mayaInput');const t=input.value;input.value='';send(t)};$('#mayaChoices').onclick=e=>{const b=e.target.closest('[data-choice]');if(b)send('',b.dataset.choice)};$('#mayaLanguage').onchange=e=>{if(busy){e.target.value=lang;return}lang=e.target.value;start()};$('#mayaRestart').onclick=()=>start();
 $('#mayaSample').onclick=()=>{audio?.pause();audio=new Audio('/assets/'+({es:'maya-es.wav',hi:'maya-hi.wav'}[lang]||'maya-welcome.wav'));audio.play().catch(()=>toast('Voice sample is not available.'))};
 $('#mayaSpeak').onclick=async()=>{try{audio?.pause();window.speechSynthesis?.cancel();if(mode==='server'&&voiceConfigured){const r=await apiFetch('/api/reception/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:response.text,language:lang})});if(!r.ok)throw Error('Voice is not yet available in this language. Text remains available.');const u=URL.createObjectURL(await r.blob());audio=new Audio(u);audio.onended=()=>URL.revokeObjectURL(u);await audio.play()}else{const code={en:'en',es:'es',hi:'hi',ur:'ur',pa:'pa',ar:'ar'}[lang],voices=speechSynthesis.getVoices().filter(v=>v.lang.startsWith(code));if(!voices.length)throw Error('Your device has no voice for this language.');const voice=voices.find(v=>/female|zira|samantha|susan|helena|sabina|heera/i.test(v.name))||voices[0];const u=new SpeechSynthesisUtterance(response.text);u.voice=voice;u.lang=voice.lang;u.rate=.9;speechSynthesis.speak(u);toast('Device voice preview; voice depends on your device.')}}catch(e){toast(e.message)}};
 $('#mayaMic').onclick=async()=>{try{if(recorder?.state==='recording'){recorder.stop();return}stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());$('#mayaMic')&&($('#mayaMic').textContent='Hold a voice turn ♩');if(!dialog.open)return;try{const blob=new Blob(chunks,{type:recorder.mimeType});const r=await apiFetch('/api/reception/transcribe',{method:'POST',headers:{'Content-Type':blob.type},body:blob});const d=await r.json();if(!r.ok)throw Error(d.error);if(d.text)await send(d.text)}catch(e){toast(e.message)}};audio?.pause();window.speechSynthesis?.cancel();recorder.start();$('#mayaMic').textContent='Stop & send recording ■';setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},20000)}catch(e){toast(e.message)}};
 await start();
}
